+<!DOCTYPE html>
+<html lang="en">
+<head>
+    <meta charset="UTF-8">
+    <meta name="viewport" content="width=device-width, initial-scale=1.0">
+    <title>Cyber-Grid Snake Game</title>
+    <style>
+        body {
+            display: flex;
+            justify-content: center;
+            align-items: center;
+            min-height: 100vh;
+            margin: 0;
+            padding: 20px;
+            background: #090d16;
+        }
+        .game-container {
+            background: rgba(16, 24, 40, 0.75);
+            backdrop-filter: blur(20px);
+            padding: 20px;
+            border-radius: 10px;
+            box-shadow: 0 0 30px rgba(56, 189, 248, 0.4);
+        }
+        .game-over-overlay {
+            display: none;
+            position: absolute;
+            top: 0;
+            left: 0;
+            width: 100%;
+            height: 100%;
+            background: rgba(0, 0, 0, 0.5);
+            justify-content: center;
+            align-items: center;
+            flex-direction: column;
+        }
+        .start-game-overlay {
+            position: absolute;
+            top: 0;
+            left: 0;
+            width: 100%;
+            height: 100%;
+            background: rgba(0, 0, 0, 0.5);
+            justify-content: center;
+            align-items: center;
+            flex-direction: column;
+        }
+        .hud {
+            display: flex;
+            justify-content: space-between;
+            padding: 12px 20px;
+        }
+    </style>
+</head>
+<body>
+    <div class="game-container">
+        <canvas id="gameCanvas" width="400" height="400"></canvas>
+        <div class="hud">
+            <span id="score">Score: 0</span>
+            <span id="high-score">High Score: 0</span>
+        </div>
+        <div class="start-game-overlay">
+            <h1>Start Game</h1>
+            <button id="play-button">Play</button>
+        </div>
+        <div class="game-over-overlay">
+            <h1>Game Over</h1>
+            <span id="final-score">Final Score: 0</span>
+            <button id="replay-button">Replay</button>
+        </div>
+    </div>
+    <script>
+        const canvas = document.getElementById('gameCanvas');
+        const ctx = canvas.getContext('2d');
+        const scoreElement = document.getElementById('score');
+        const highScoreElement = document.getElementById('high-score');
+        const playButton = document.getElementById('play-button');
+        const replayButton = document.getElementById('replay-button');
+        const finalScoreElement = document.getElementById('final-score');
+        const gameOverOverlay = document.querySelector('.game-over-overlay');
+        const startGameOverlay = document.querySelector('.start-game-overlay');
+        let score = 0;
+        let highScore = localStorage.getItem('highScore') || 0;
+        let snake = [
+            { x: 200, y: 200 },
+            { x: 190, y: 200 },
+            { x: 180, y: 200 }
+        ];
+        let direction = 'right';
+        let food = { x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10 };
+        let powerUps = [];
+        let speedBoost = false;
+        let scoreMultiplier = 1;
+        let shield = false;
+        let gameOver = false;
+        let lastTick = 0;
+        let audioContext = new AudioContext();
+        let eatSound = new Audio('eat.mp3');
+        let gameOverSound = new Audio('game-over.mp3');
+        let speedBoostSound = new Audio('speed-boost.mp3');
+        let scoreMultiplierSound = new Audio('score-multiplier.mp3');
+        let shieldSound = new Audio('shield.mp3');
+        
+        function draw() {
+            ctx.clearRect(0, 0, canvas.width, canvas.height);
+            ctx.fillStyle = 'rgba(16, 24, 40, 0.75)';
+            ctx.fillRect(0, 0, canvas.width, canvas.height);
+            for (let i = 0; i < snake.length; i++) {
+                ctx.fillStyle = 'rgba(0, 255, 0, 0.5)';
+                ctx.fillRect(snake[i].x, snake[i].y, 10, 10);
+            }
+            ctx.fillStyle = 'rgba(255, 0, 0, 0.5)';
+            ctx.fillRect(food.x, food.y, 10, 10);
+            for (let i = 0; i < powerUps.length; i++) {
+                ctx.fillStyle = 'rgba(0, 0, 255, 0.5)';
+                ctx.fillRect(powerUps[i].x, powerUps[i].y, 10, 10);
+            }
+        }
+        
+        function update() {
+            if (gameOver) return;
+            const now = Date.now();
+            if (now - lastTick < 100) return;
+            lastTick = now;
+            for (let i = snake.length - 1; i > 0; i--) {
+                snake[i] = { ...snake[i - 1] };
+            }
+            if (direction === 'right') {
+                snake[0].x += 10;
+            } else if (direction === 'left') {
+                snake[0].x -= 10;
+            } else if (direction === 'up') {
+                snake[0].y -= 10;
+            } else if (direction === 'down') {
+                snake[0].y += 10;
+            }
+            if (snake[0].x === food.x && snake[0].y === food.y) {
+                eatSound.play();
+                score += scoreMultiplier;
+                scoreElement.textContent = `Score: ${score}`;
+                food = { x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10 };
+                snake.push({ x: snake[snake.length - 1].x, y: snake[snake.length - 1].y });
+            }
+            for (let i = 1; i < snake.length; i++) {
+                if (snake[0].x === snake[i].x && snake[0].y === snake[i].y) {
+                    gameOverSound.play();
+                    gameOver = true;
+                    gameOverOverlay.style.display = 'flex';
+                    finalScoreElement.textContent = `Final Score: ${score}`;
+                }
+            }
+            if (snake[0].x < 0 || snake[0].x >= canvas.width || snake[0].y < 0 || snake[0].y >= canvas.height) {
+                gameOverSound.play();
+                gameOver = true;
+                gameOverOverlay.style.display = 'flex';
+                finalScoreElement.textContent = `Final Score: ${score}`;
+            }
+            draw();
+        }
+        
+        function handleKeyDown(event) {
+            if (event.key === 'ArrowRight' && direction !== 'left') {
+                direction = 'right';
+            } else if (event.key === 'ArrowLeft' && direction !== 'right') {
+                direction = 'left';
+            } else if (event.key === 'ArrowUp' && direction !== 'down') {
+                direction = 'up';
+            } else if (event.key === 'ArrowDown' && direction !== 'up') {
+                direction = 'down';
+            }
+        }
+        
+        function handleTouch(event) {
+            const touch = event.touches[0];
+            const x = touch.clientX;
+            const y = touch.clientY;
+            if (x > canvas.width / 2 && direction !== 'left') {
+                direction = 'right';
+            } else if (x < canvas.width / 2 && direction !== 'right') {
+                direction = 'left';
+            } else if (y > canvas.height / 2 && direction !== 'up') {
+                direction = 'down';
+            } else if (y < canvas.height / 2 && direction !== 'down') {
+                direction = 'up';
+            }
+        }
+        
+        playButton.addEventListener('click', () => {
+            startGameOverlay.style.display = 'none';
+            update();
+            setInterval(update, 100);
+        });
+        
+        replayButton.addEventListener('click', () => {
+            gameOver = false;
+            score = 0;
+            snake = [
+                { x: 200, y: 200 },
+                { x: 190, y: 200 },
+                { x: 180, y: 200 }
+            ];
+            direction = 'right';
+            food = { x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10 };
+            powerUps = [];
+            speedBoost = false;
+            scoreMultiplier = 1;
+            shield = false;
+            gameOverOverlay.style.display = 'none';
+            update();
+            setInterval(update, 100);
+        });
+        
+        document.addEventListener('keydown', handleKeyDown);
+        canvas.addEventListener('touchstart', handleTouch);
+        
+        if (score > highScore) {
+            highScore = score;
+            localStorage.setItem('highScore', highScore);
+            highScoreElement.textContent = `High Score: ${highScore}`;
+        }
+    </script>
+</body>
+</html>

